    rulesL16_1j: "наличии иных законных оснований.",
    rulesP16_2: "16.2. При необходимости AGROMAL вправе запросить дополнительные сведения или документы до восстановления лота.",
    rulesP16_3: "16.3. Восстановление лота после устранения причин приостановления не является автоматической обязанностью AGROMAL.",
