    rulesL17_2e: "прекращение доступа к платформе.",
    rulesP17_3: "17.3. Применение ограничений не лишает пользователя прав, которые не могут быть ограничены в соответствии с законодательством Кыргызской Республики.",
    rulesS18: "18. ВЗАИМОДЕЙСТВИЕ ПРИ СПОРАХ",
    rulesP18_1: "18.1. Споры, возникающие из договора купли-продажи животных, разрешаются непосредственно между Поставщиком и Закупщиком.",
    rulesP18_2: "18.2. AGROMAL не является арбитром либо стороной договора купли-продажи, если иное прямо не предусмотрено отдельным соглашением.",
    rulesP18_3: "18.3. При наличии технической возможности AGROMAL вправе содействовать сторонам в обмене информацией, предоставлении имеющихся материалов и фиксации сведений о проведённых через платформу процедурах.",
    rulesP18_4: "18.4. Такое содействие не означает принятия AGROMAL на себя обязательств Поставщика или Закупщика и не означает признания AGROMAL ответственным за исполнение договора купли-продажи.",
