    rulesP19_3: "19.3. Положения настоящего раздела не ограничивают использование информации в случаях, когда её раскрытие или предоставление прямо требуется законодательством Кыргызской Республики.",
    rulesS20: "20. ИЗМЕНЕНИЕ ПРАВИЛ",
    rulesP20_1: "20.1. AGROMAL вправе изменять настоящие Правила в связи с изменением законодательства, функциональности платформы, порядка формирования и проверки лотов либо иных условий работы сервиса.",
    rulesP20_2: "20.2. Актуальная редакция Правил публикуется на сайте AGROMAL с указанием даты публикации и даты вступления в силу.",
    rulesP20_3: "20.3. Если изменение Правил одновременно изменяет условия пользовательского соглашения между AGROMAL и пользователем, применяются требования к изменению соответствующих договорных условий, установленные законодательством Кыргызской Республики и Условиями сервиса.",
    rulesS21: "21. ОСНОВНОЙ ПРИНЦИП AGROMAL",
