    lotsNoticeBody: "Сүрөттөр, видеолор, толук мүнөздөмөлөр жана коммерциялык шарттар каттодон жана сатып алуучунун статусын ырастоодон кийин жеткиликтүү.",
    lotsNoticeTitle: "Купуялык режими.",

