/* =========================================================
   LANGUAGE HELPERS
   ========================================================= */

const aliases = {
  kg: "ky",
  ky: "ky",
  ru: "ru",
  en: "en"
};


function savedLanguage() {
  try {
    return localStorage.getItem("agromal_language");
  } catch {
    return null;
  }
}


let current =
  aliases[savedLanguage()] || "ru";

/* =========================================================
   KG LAYOUT LOCK
   KG = единственный эталон геометрии интерфейса.
   RU / EN меняют только текст.
   ========================================================= */

let kgLayoutLocked = false;

const kgLayoutSelectors = [
  /* HEADER */
  ".site-header__inner",
  ".brand",
  ".brand__logo",
  ".brand__name",
  ".brand__tag",
  ".brand-divider",
  ".lang-switch",
  ".lang-switch button",

  /* HOMEPAGE */
  "body.homepage .hero__grid--reference",
  "body.homepage .hero__board",
  "body.homepage .ref-rail",
  "body.homepage .ref-rail__item",
  "body.homepage .hero__content--reference",
  "body.homepage .hero-b2b-title",
  "body.homepage .hero-b2b-formula",
  "body.homepage .hero-b2b-principles-wrap",
  "body.homepage .hero-b2b-principles",
  "body.homepage .hero-b2b-principles li",
  "body.homepage .ref-feature-grid",
  "body.homepage .ref-feature",
  "body.homepage .hero-b2b-systems",

  /* TERMINAL */
  "body.homepage .hero__terminal",
  "body.homepage .login-panel",
  "body.homepage .panel__head",
  "body.homepage .field",
  "body.homepage .field input",
  "body.homepage .login-submit",
  "body.homepage .hero-access",
  "body.homepage .hero-access-card",
  "body.homepage .hero-assist",
  "body.homepage .hero-help",
  "body.homepage .hero-trust",

  /* PUBLIC LOTS */
  "body.homepage .homepage-demo-lots",
  "body.homepage .homepage-demo-lots__notice",
  "body.homepage .homepage-lot",

  /* LEGAL */
  "body.homepage .homepage-legal",
  "body.homepage .homepage-legal__inner"
];
function lockKgLayout() {
  if (kgLayoutLocked) {
    return;
  }

  if (
    !document.body ||
    !document.body.classList.contains("homepage")
  ) {
    kgLayoutLocked = true;
    return;
  }

  const elements = [];

  kgLayoutSelectors.forEach((selector) => {
    document
      .querySelectorAll(selector)
      .forEach((element) => {
        if (!elements.includes(element)) {
          elements.push(element);
        }
      });
  });

  elements.forEach((element) => {
    const rect = element.getBoundingClientRect();

    if (
      !rect.width ||
      !rect.height
    ) {
      return;
    }

    const computed =
      window.getComputedStyle(element);

    /*
     * Запоминаем именно фактический размер KG,
     * который браузер уже рассчитан.
     */

    element.style.width =
      `${Math.ceil(rect.width)}px`;

    element.style.minWidth =
      `${Math.ceil(rect.width)}px`;

    element.style.maxWidth =
      `${Math.ceil(rect.width)}px`;

    element.style.height =
      `${Math.ceil(rect.height)}px`;

    element.style.minHeight =
      `${Math.ceil(rect.height)}px`;

    element.style.maxHeight =
      `${Math.ceil(rect.height)}px`;

    /*
     * Для flex/grid запрещаем элементу
     * заново менять геометрию.
     */

    if (
      computed.display === "flex" ||
      computed.display === "inline-flex"
    ) {
      element.style.flexShrink = "0";
    }

    /*
     * Длинный перевод не имеет права
     * растягивать коробку.
     */

    element.style.boxSizing =
      "border-box";

    if (
      element.matches(
        "button, .button, .hero-access-card"
      )
    ) {
      element.style.overflow = "hidden";
    }
  });

  /*
   * Особенно важно для шапки:
   * KG / РУС / ENG всегда занимают
   * одинаковые места.
   */

  document
    .querySelectorAll(
      ".lang-switch"
    )
    .forEach((switcher) => {
      const buttons =
        switcher.querySelectorAll(
          "button"
        );

      buttons.forEach((button) => {
        button.style.flexShrink = "0";
        button.style.whiteSpace = "nowrap";
        button.style.overflow = "hidden";
      });
    });

  kgLayoutLocked = true;
}

/* =========================================================
   STANDARD TRANSLATION
   ========================================================= */

export function t(key) {
  return (
    messages[current]?.[key] ??
    messages.ru?.[key] ??
    key
  );
}


/* =========================================================
   DYNAMIC TRANSLATION
   Для значений из БД / Supabase.
   ========================================================= */

export function td(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return "";
  }

  const raw =
    String(value).trim();

  if (!raw) {
    return "";
  }

  return (
    dynamicTranslations[current]?.[raw] ??
    dynamicTranslations.ru?.[raw] ??
    raw
  );
}


/* =========================================================
   LANGUAGE
   ========================================================= */

export function language() {
  return current;
}


/* =========================================================
   APPLY LANGUAGE
   ========================================================= */

export function applyLanguage(
  lang = current
) {
  current =
    aliases[lang] || "ru";

  try {
    localStorage.setItem(
      "agromal_language",
      current
    );
  } catch {
    // Preference persistence is optional.
  }


  document.documentElement.lang =
    current === "ky"
      ? "ky"
      : current;


  /* =====================================================
     TEXT CONTENT
     ===================================================== */

  document
    .querySelectorAll(
      "[data-i18n]"
    )
    .forEach((element) => {
      const key =
        element.dataset.i18n;

      if (!key) {
        return;
      }

      const value =
        t(key);

      if (
        typeof value === "string" &&
        value.includes("\n")
      ) {
        element.innerHTML =
          value
            .split("\n")
            .map(
              (line) =>
                escapeHtml(line)
            )
            .join("<br>");
      } else {
        element.textContent =
          value;
      }
    });


  /* =====================================================
     PLACEHOLDERS
     ===================================================== */

  document
    .querySelectorAll(
      "[data-i18n-placeholder]"
    )
    .forEach((element) => {
      const key =
        element.dataset
          .i18nPlaceholder;

      if (!key) {
        return;
      }

      element.placeholder =
        t(key);
    });


  /* =====================================================
     ARIA LABELS
     ===================================================== */

  document
    .querySelectorAll(
      "[data-i18n-aria-label]"
    )
    .forEach((element) => {
      const key =
        element.dataset
          .i18nAriaLabel;

      if (!key) {
        return;
      }

      element.setAttribute(
        "aria-label",
        t(key)
      );
    });


  /* =====================================================
     TITLE ATTRIBUTES
     ===================================================== */

  document
    .querySelectorAll(
      "[data-i18n-title]"
    )
    .forEach((element) => {
      const key =
        element.dataset
          .i18nTitle;

      if (!key) {
        return;
      }

      element.setAttribute(
        "title",
        t(key)
      );
    });


  /* =====================================================
     DOCUMENT TITLE
     ===================================================== */

  const titleKey =
    document.documentElement
      .dataset.i18nTitle;

  if (titleKey) {
    document.title =
      t(titleKey);
  }


  /* =====================================================
     LANGUAGE BUTTONS
     ===================================================== */

  document
    .querySelectorAll(
      "[data-lang]"
    )
    .forEach((button) => {
      const active =
        aliases[
          button.dataset.lang
        ] === current;

      button.classList.toggle(
        "is-active",
        active
      );

      button.setAttribute(
        "aria-current",
        String(active)
      );
      button.setAttribute(
        "aria-pressed",
        String(active)
      );
    });


  /* =====================================================
     EVENT
     ===================================================== */

  document.dispatchEvent(
    new CustomEvent(
      "agromal:language",
      {
        detail: current
      }
    )
  );
}


/* =========================================================
   INIT
   ========================================================= */

export function initI18n() {
  document
    .querySelectorAll(
      "[data-lang]"
    )
    .forEach((button) => {
      button.addEventListener(
        "click",
        () => {
          applyLanguage(
            button.dataset.lang
          );
        }
      );
    });

  applyLanguage(current);
}


/* =========================================================
   SAFE HTML ESCAPE
   ========================================================= */

function escapeHtml(value) {
  return String(value)
    .replaceAll(
      "&",
      "&amp;"
    )
    .replaceAll(
      "<",
      "&lt;"
    )
    .replaceAll(
      ">",
      "&gt;"
    )
    .replaceAll(
      '"',
      "&quot;"
    )
    .replaceAll(
      "'",
      "&#039;"
    );
}